-- kalimdor: each item's best drop chance (%), for the bots' value of an item
-- (playerbots values/AuctionGoods.h; Kamino 271).
--
-- Upstream works this out from the loot tables (RandomItemMgr::
-- BuildRarityCache: creature, gameobject, disenchant, fishing and skinning
-- loot) but never runs it - 0.1-0.6 s an item, about half an hour for all.
-- Worked out once with its query on the dev server's world database
-- (2026-11-07) and shipped here; the world server reads it at its start
-- (RandomItemMgr::LoadItemRarity). Left out: items no loot table holds, a
-- chance of 0.01% or less (upstream keeps none of those either), and items a
-- vendor sells - Engineer's Ink came out at 0.02%.
--
-- It can run again: the table is filled anew each time.
CREATE TABLE IF NOT EXISTS `kalimdor_item_rarity` (
  `item` mediumint(8) unsigned NOT NULL,
  `chance` float NOT NULL,
  PRIMARY KEY (`item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='kalimdor: best drop chance per item (Kamino 271)';

DELETE FROM `kalimdor_item_rarity`;
